                        min: 0,
                        max: Math.max(100, info.maxY),
                        labelWidth: 145,
                        reserveSpace: true,
                        lineWidth: 0.5,
                        color: '#000',
                        tickFormatter: getPercentTickFormatter(Math.max(100, info.maxY)),
                        minTickSize: 1
                    },
