                var contigNo = 0;
                var totalFull = 0;

                for (var k = 0; k < featureInContigs.length; k++) {
                    contigNo += 1;
                    totalFull += featureInContigs[k];

                    info.series[fi].data.push([contigNo, totalFull]);

                    if (info.series[fi].data[k][1] > info.maxY) {
                        info.maxY = info.series[fi].data[k][1];
                    }
