    }

  , validate: function () {
      if (!this.$element[0].parentNode) {
        this.hide();
        this.$element = null;
        this.options = null;
      }
    }

  , enable: function () {
      this.enabled = true;
    }

  , disable: function () {
      this.enabled = false;
    }

  , toggleEnabled: function () {
      this.enabled = !this.enabled;
    }

  , toggle: function () {
